import math

def phi(n):
    """Calculates Euler's totient function phi(n)."""
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def multiplicative_order(a, n):
    """Calculates the multiplicative order of a modulo n, ord_n(a)."""
    if math.gcd(a, n) != 1:
        # Should not happen for relevant D since 3 is not divisible by 3
        # Wait, if n=3, gcd(3, 3) = 3. But we check D>=2. 
        # Since we iterate m such that 3 \nmid m, all divisors D also satisfy 3 \nmid D, so gcd(3, D) = 1.
        return None 

    # The order must divide phi(n). We iterate powers up to phi(n).
    p = phi(n)

    # Check divisors of phi(n) for efficiency, but simple iteration is fine for n < 200.
    k = 1
    current_power = a % n
    while k <= p:
        if current_power == 1:
            return k
        current_power = (current_power * a) % n
        k += 1
    return None # Should theoretically not be reached if gcd(a,n)=1

def calculate_f(D):
    """Calculates f(D) = phi(D) / ord_D(3)."""
    if D <= 1:
        return 0

    # Since we iterate m such that 3 \nmid m, we are guaranteed 3 \nmid D, so gcd(3, D) = 1.
    order = multiplicative_order(3, D)
    if order is None:
        # Should be impossible given the constraints on m
        return 0 

    # Since the order must divide phi(D), this division should result in an integer.
    return phi(D) // order

# --- Step 1 & 2: Pre-calculate f(D) for D in [2, 199] ---
