import math

def phi(n):
    """Euler's totient function phi(n)."""
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def multiplicative_order(base, modulus):
    """Calculates the multiplicative order of base modulo modulus, ord_mod(base)."""
    if gcd(base, modulus) != 1:
        # Order is undefined or requires careful handling if not coprime.
        # Based on the formula context, we assume D is chosen such that gcd(3, D)=1.
        return 0

    phi_m = phi(modulus)

    # Check divisors of phi_m
    for k in range(1, phi_m + 1):
        if phi_m % k == 0:
            if pow(base, k, modulus) == 1:
                return k
    return phi_m # Should not happen if phi_m is correct

# 1. Calculate f(D) = phi(D) / ord_D(3) for D in [2, 199]
f_values = {}
for D in range(2, 200):
    if gcd(3, D) == 1:
        try:
            ord_3_D = multiplicative_order(3, D)
            if ord_3_D > 0:
                f_D = phi(D) / ord_3_D
                # Since the formula is used in a sum for N_C(m), 
                # we assume f_D must be an integer for the problem to be well-posed 
                # in elementary number theory context, although we should keep it float 
                # until the summation if needed.
                # Based on W1's note, we proceed with the formula as stated.
                f_values[D] = f_D
            else:
                f_values[D] = 0
        except Exception:
            f_values[D] = 0
    else:
        # If gcd(3, D) != 1, f(D) might be undefined or 0 based on the context
        f_values[D] = 0

print("f_values calculated.")

# 2. Calculate N_C(m) for m < 200, 3 \nmid m
odd_nc_m = []

for m in range(2, 200):
    if m % 3 == 0:
        continue

    n_c_m = 0

    # Iterate over divisors D > 1
    divisors = []
    for D in range(2, m + 1):
        if m % D == 0:
            divisors.append(D)

    for D in divisors:
        if D in f_values:
            n_c_m += f_values[D]

    if n_c_m % 2 != 0:
        odd_nc_m.append(m)

# 3. Find the second largest m
odd_nc_m.sort(reverse=True)

if len(odd_nc_m) >= 2:
    second_largest = odd_nc_m[1]
    print(f"List of m with odd N_C(m) (largest to smallest): {odd_nc_m}")
    print(f"The second largest m is: {second_largest}")
else:
    print("Fewer than two such m found.")

def count_cycles(m):
    if m % 3 == 0:
        return -1 # Invalid m

    visited = [False] * m
    cycle_count = 0

    for start_node in range(1, m):
        if not visited[start_node]:
            cycle_count += 1

            current = start_node
            # Trace the cycle
            while not visited[current]:
                visited[current] = True
                current = (3 * current) % m

    return cycle_count

# Check m downwards from 199
m_values = []
for m in range(199, 0, -1):
    if m % 3 != 0:
        C = count_cycles(m)
        if C % 2 != 0:
            m_values.append(m)

print("Candidate m values (in descending order):", m_values)

